#!/usr/bin/env sh
# File: scripts/check-x8664-kaslr-runtime.sh
# Purpose: Boot a relocated PC kernel, and prove the table describes it.
#
# Why this exists
# ---------------
# With the `kaslr` feature on, `kernel_entry` copies the image to a base the
# machine's memory map allows, patches the compiled-in relocation table's
# sites by the delta, and continues in the copy.  Two things can be wrong
# about that, and both are silent without a gate:
#
#   * the table can describe a *different* build.  It is generated by
#     `make gen-kaslr-relocs` and compiled in, so a tree whose layout moved
#     since the last generation carries a table naming the wrong sites.  The
#     array's length is fixed exactly so that two generations agree
#     (`RELOCATION_CAPACITY` in the tool), and this gate is what holds the
#     tree to that: it regenerates from the built image and requires the
#     result to be byte-identical to the checked-in table.
#   * the copy can be wrong even when the table is right — the first boot of
#     this feature died at `Formatter::pad`'s link-time address, because the
#     fmt/alloc dispatch slots in `.data` had been resolved by the linker
#     with no relocation record for the generator to follow.  The boot below
#     is what exercises the fix: the demo reaches its shell, so every
#     indirect call through a patched slot landed in the copy.
#
# What the boot has to show:
#
#   * the relocation line, with a nonzero delta — a boot that silently
#     stayed at the link address has not tested anything.
#   * the kernel's *own* symbol-derived view moved with it: the image range
#     the memory report prints starts at the relocated base, and the pool's
#     range starts past it.  Those numbers come from linker symbols through
#     the table, so this is the end-to-end check that the sites were patched.
#   * the demo reaches its shell and answers a typed line — the copy's code,
#     its strings, and its dispatch slots all work.
#   * a machine with several CPUs brings those CPUs up *in the copy*: the
#     trampoline's only link-time value is `ap_entry`'s address, it is a
#     relocated site, and every other field it reads is a runtime value — so
#     the assertion is that the APs come online and dispatch threads, which
#     is what a boot that ran an AP into the abandoned image could not do.
#   * a machine too small for the copy refuses a placement and boots at the
#     link address, which is the branch a small machine really takes.

set -eu

cd "$(dirname "$0")/.."

PROFILE="${PROFILE:-debug}"
CRATE="${CRATE:-protofire}"
CARGO="${CARGO:-cargo}"
TARGET_DIR="${TARGET_DIR:-target}"
TIMEOUT_SECONDS="${TIMEOUT_SECONDS:-60}"
QEMU="${QEMU:-qemu-system-x86_64}"
X8664_KASLR_LOG="${X8664_KASLR_LOG:-}"
FEATURES="${FEATURES:-demo-disk kaslr}"

KERNEL_BIN="${TARGET_DIR}/x86_64-unknown-none/${PROFILE}/${CRATE}"
TABLE="src/arch/x86_64/kaslr_relocs.generated.rs"

case "$PROFILE" in
    debug|release) ;;
    *)
        printf 'unsupported PROFILE: %s\n' "$PROFILE" >&2
        exit 1
        ;;
esac

if ! command -v "$QEMU" >/dev/null 2>&1; then
    printf '%s is not installed; cannot run the KASLR runtime check.\n' "$QEMU" >&2
    exit 1
fi

# The placed-as-linked assertion reads the image's program headers, its type,
# its entry and its `_start` symbol with the binutils the build already
# depends on.  Say which is missing rather than failing mid-assertion with a
# parse error that reads as an image defect.
for tool in readelf nm objdump; do
    if ! command -v "$tool" >/dev/null 2>&1; then
        printf '%s is not installed; the KASLR check asserts the image format.\n' "$tool" >&2
        exit 1
    fi
done

case "$PROFILE" in
    release) profile_flag="--release" ;;
    *) profile_flag="" ;;
esac

printf 'x86_64 KASLR check: building with "%s"\n' "$FEATURES"
"$CARGO" build --offline $profile_flag --target x86_64-unknown-none --bin "$CRATE" \
    --features "$FEATURES"

# The freshness half: the table compiled into this image has to be the table
# this image generates.  One regeneration is enough because the array's
# length is fixed — a second pass would produce the same layout and the same
# table (the tool's comment argues it, and the fixed-point check in the
# commit that added this gate measured it).
fresh="$(mktemp)"
gen_log="$(mktemp)"
set +e
"$CARGO" run --offline -q -p gen-kaslr-relocs -- "$KERNEL_BIN" "$fresh" >"$gen_log" 2>&1
gen_status=$?
set -e
if [ "$gen_status" -ne 0 ]; then
    printf 'x86_64 KASLR check failed: the generator could not read %s\n' "$KERNEL_BIN" >&2
    rm -f "$fresh" "$gen_log"
    exit 1
fi
if ! cmp -s "$fresh" "$TABLE"; then
    printf 'x86_64 KASLR check failed: %s does not describe %s\n' "$TABLE" "$KERNEL_BIN" >&2
    printf 'the relocation table is stale; run `make gen-kaslr-relocs` and rebuild\n' >&2
    rm -f "$fresh" "$gen_log"
    exit 1
fi
printf '  table is fresh: the checked-in relocation list equals the one this image generates\n'

# And the scan that complements the relocation records has to have found
# something: those records are the only source for the fmt/alloc dispatch
# slots, and a scan that silently matched nothing would still produce a table
# equal to itself — the boot below is what catches that, but naming it here
# costs one line and points at the cause.
scanned="$(grep -a -o 'scanned: [0-9]*' "$gen_log" | head -n 1 | awk '{print $2}')"
if [ -z "$scanned" ] || [ "$scanned" -eq 0 ]; then
    printf 'x86_64 KASLR check failed: the generator scanned no pointer outside the relocation records (scanned=%s)\n' "$scanned" >&2
    printf 'the dispatch slots in .data carry no relocation record; without the scan the copy calls into the abandoned image\n' >&2
    rm -f "$fresh" "$gen_log"
    exit 1
fi
printf '  the scan carried %s pointer(s) with no relocation record\n' "$scanned"
rm -f "$fresh" "$gen_log"

# The relocator assumes the loader placed the kernel at its link address: the
# table's offsets are measured from there, and the copy's sites are patched by
# the delta between the two.  The assumption is a property of the image, not
# of a loader, and it holds for any loader that honours the ELF's own
# addresses — so what this asserts is exactly those properties, on the image
# the boot below runs: every PT_LOAD maps its physical address at its virtual
# address (an ELF a loader would have to move somewhere else would say
# otherwise), the ELF is ET_EXEC (nothing invites a dynamic relocation pass),
# and the entry the loader jumps to is `_start`'s linked address.
pt_mismatch="$(
    LC_ALL=C readelf -lW "$KERNEL_BIN" \
        | awk '$1 == "LOAD" && $3 != $4 { print; exit }'
)"
if [ -n "$pt_mismatch" ]; then
    printf 'x86_64 KASLR check failed: a PT_LOAD maps p_paddr != p_vaddr:\n%s\n' "$pt_mismatch" >&2
    printf 'the relocator assumes the loader placed the kernel at its link address\n' >&2
    exit 1
fi
elf_type="$(LC_ALL=C readelf -h "$KERNEL_BIN" | awk -F: '/Type:/ { gsub(/^[ \t]+/, "", $2); print $2 }')"
case "$elf_type" in
    EXEC*|*EXEC*) ;;
    *)
        printf 'x86_64 KASLR check failed: %s is %s, not ET_EXEC\n' "$KERNEL_BIN" "$elf_type" >&2
        printf 'the relocator assumes a loader that does not run a relocation pass of its own\n' >&2
        exit 1
        ;;
esac
entry="$(LC_ALL=C readelf -h "$KERNEL_BIN" | awk -F: '/Entry point address/ { gsub(/^[ \t]+/, "", $2); print $2 }')"
start_addr="$(nm "$KERNEL_BIN" 2>/dev/null | awk '$3 == "_start" { print $1; exit }')"
if [ -z "$entry" ] || [ -z "$start_addr" ]; then
    printf 'x86_64 KASLR check failed: could not read the entry point from %s\n' "$KERNEL_BIN" >&2
    exit 1
fi
entry_num="$(printf '%d' "0x${entry#0x}")"
start_num="$(printf '%d' "0x${start_addr#0x}")"
if [ "$entry_num" != "$start_num" ]; then
    printf 'x86_64 KASLR check failed: entry is %s, _start is %s\n' "$entry" "$start_addr" >&2
    printf 'the boot stub entered is not the linked _start the relocator measured from\n' >&2
    exit 1
fi
printf '  the kernel is placed-as-linked: ET_EXEC, every LOAD p_paddr == p_vaddr, entry == _start\n'

# And the build identity is isolated from everything the table describes.
# Its *content* follows git state (`git describe --dirty`), and this
# toolchain hashes a constant's bytes into the symbol names that order the
# items around it — measured, two 16-byte identities of different content
# moved nineteen `.rodata`-relative table sites.  The fix is the section, so
# the section is what is asserted: a change that moved the value back into
# `.rodata` would pass this gate while working in the tree that generated
# the table, and fail on the next clean checkout.
# `objdump -h` puts the size in a fixed column; `readelf`'s is harder to pick
# apart from the offset and alignment, which are hex too.
kaslr_id_size="$(objdump -h "$KERNEL_BIN" 2>/dev/null | awk '$2 == ".kaslr_id" { print $3 }' | head -n 1)"
if [ -z "$kaslr_id_size" ]; then
    printf 'x86_64 KASLR check failed: the image has no .kaslr_id section\n' >&2
    printf 'the build identity must be isolated from the layout the table describes (see src/arch/entry.rs)\n' >&2
    exit 1
fi
if [ "$((0x$kaslr_id_size))" -ne 16 ]; then
    printf 'x86_64 KASLR check failed: .kaslr_id is %s bytes, not the fixed 16 (see BUILD_ID_WIDTH)\n' "${kaslr_id_size:-0}" >&2
    exit 1
fi
printf '  the build identity is isolated in .kaslr_id (%s bytes)\n' "$kaslr_id_size"

if [ -n "$X8664_KASLR_LOG" ]; then
    mkdir -p "$(dirname "$X8664_KASLR_LOG")"
    log_file="$X8664_KASLR_LOG"
    : >"$log_file"
    remove_log_on_exit=0
else
    log_file="$(mktemp)"
    remove_log_on_exit=1
fi

cleanup() {
    if [ "$remove_log_on_exit" = "1" ]; then
        rm -f "$log_file"
    fi
}
trap cleanup EXIT INT TERM

fail_with_log() {
    printf 'x86_64 KASLR check failed: %s\n' "$1" >&2
    cat "$log_file" >&2
    exit 1
}

require_log_line() {
    pattern="$1"
    if ! grep -a -F "$pattern" "$log_file" >/dev/null 2>&1; then
        fail_with_log "missing log line: $pattern"
    fi
}

require_log_absent_line() {
    pattern="$1"
    if grep -a -F "$pattern" "$log_file" >/dev/null 2>&1; then
        fail_with_log "unexpected log line: $pattern"
    fi
}

require_log_exact_line() {
    line="$1"
    if ! grep -a -F -x "$line" "$log_file" >/dev/null 2>&1; then
        fail_with_log "missing log line (whole line): $line"
    fi
}

# ── One CPU: the relocation path, end to end ──────────────────────────
printf '  %s\n' "shell_commands | timeout ${TIMEOUT_SECONDS}s $QEMU -machine q35 -smp 1 -m 1G ... -serial stdio"
shell_commands() {
    sh ./scripts/feed-shell-console.sh "$log_file" "$TIMEOUT_SECONDS" \
        'echo ring3-shell-answered'
}
set +e
shell_commands | timeout "${TIMEOUT_SECONDS}s" "$QEMU" \
    -machine q35 \
    -cpu max \
    -smp 1 \
    -m 1G \
    -kernel "$KERNEL_BIN" \
    -display none \
    -serial stdio \
    -no-reboot \
    -no-shutdown \
    -netdev user,id=net0 -device virtio-net-pci,netdev=net0 >"$log_file" 2>&1
status=$?
set -e
case "$status" in
    0|124) ;;
    *)
        printf 'x86_64 KASLR check failed with exit status %s\n' "$status" >&2
        cat "$log_file" >&2
        exit "$status"
        ;;
esac

# The relocation happened, and the delta is real.
relocated="$(grep -a -o '\[kaslr \] relocated to 0x[0-9a-f]*' "$log_file" | head -n 1 | sed 's/.*0x//')"
if [ -z "$relocated" ]; then
    fail_with_log 'the boot did not report a relocation (the machine offered no placement, or the feature is off)'
fi
delta="$(grep -a -o '\[kaslr \] relocated to 0x[0-9a-f]* (delta 0x[0-9a-f]*)' "$log_file" | head -n 1 | sed 's/.*delta 0x//; s/)$//')"
if [ -z "$delta" ] || [ "$delta" = "0" ]; then
    fail_with_log "the boot relocated to its own link address (delta=$delta)"
fi
printf '  relocated to 0x%s (delta 0x%s)\n' "$relocated" "$delta"

# The kernel's symbol-derived view moved with it: the image range starts at
# the relocated base, and the pool starts past it.  Both numbers come from
# linker symbols through the table.
require_log_line "[mem   ] the kernel's image [0x${relocated},"
pool_start="$(grep -a -o '\[mem   \] the pool is \[0x[0-9a-f]*' "$log_file" | head -n 1 | sed 's/.*0x//')"
if [ -z "$pool_start" ]; then
    fail_with_log 'the boot did not report the pool'
fi
# Numeric, not lexical: the two are printed without leading zeros, so a
# string comparison would call 0x2e387000 smaller than 0xf200000 (it starts
# with a lower character) and fail a boot that is fine.
if [ "$((0x$pool_start))" -le "$((0x$relocated))" ]; then
    fail_with_log "the pool (0x$pool_start) did not move with the kernel (0x$relocated)"
fi
printf '  the image and the pool report the relocated base: image at 0x%s, pool at 0x%s\n' "$relocated" "$pool_start"

require_log_line "protofire ring3 shell"
require_log_exact_line "ring3-shell-answered"
require_log_absent_line "[FATAL"

# ── Several CPUs: the APs really come up in the copy ──────────────────
# The trampoline's one link-time value is `ap_entry`'s address, and the
# relocation table carries that site, so the copy's immediate names the
# copy's entry; every other field the trampoline reads is a runtime value.
# That is a measurement, not an argument: this boot differs from the one
# above only in `-smp`, and it requires the APs to come online and dispatch
# threads — a machine that ran an AP into the abandoned image would fault or
# hang there rather than reach the assertions below.
smp_log="$(mktemp)"
printf '  %s\n' "timeout ${TIMEOUT_SECONDS}s $QEMU -machine q35 -smp 4 -m 1G ... -serial file:"
set +e
timeout "${TIMEOUT_SECONDS}s" "$QEMU" \
    -machine q35 \
    -cpu max \
    -smp 4 \
    -m 1G \
    -kernel "$KERNEL_BIN" \
    -display none \
    -serial "file:$smp_log" \
    -no-reboot \
    -no-shutdown \
    -netdev user,id=net0 -device virtio-net-pci,netdev=net0 >/dev/null 2>>"$smp_log"
status=$?
set -e
case "$status" in
    0|124) ;;
    *)
        printf 'x86_64 KASLR check failed with exit status %s on the SMP machine\n' "$status" >&2
        cat "$smp_log" >&2
        rm -f "$smp_log"
        exit "$status"
        ;;
esac
online="$(grep -a -c 'AP cpu_id=[0-9]* lapic_id=[0-9]* online' "$smp_log" || true)"
if [ "${online:-0}" -lt 3 ]; then
    printf 'x86_64 KASLR check failed: only %s AP(s) came online of 3 under relocation\n' "$online" >&2
    cat "$smp_log" >&2
    rm -f "$smp_log"
    exit 1
fi
if ! grep -a -F "cpu=1 dispatched its first thread" "$smp_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: an AP came online but never dispatched a thread\n' >&2
    cat "$smp_log" >&2
    rm -f "$smp_log"
    exit 1
fi
if grep -a -F "SMP: bringing up 0 AP" "$smp_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the relocated kernel skipped AP bring-up\n' >&2
    cat "$smp_log" >&2
    rm -f "$smp_log"
    exit 1
fi
printf '  %s APs online in the copy, threads dispatching\n' "$online"
if ! grep -a -F "protofire ring3 shell" "$smp_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the SMP machine did not reach the shell\n' >&2
    cat "$smp_log" >&2
    rm -f "$smp_log"
    exit 1
fi
if grep -a -F "[FATAL" "$smp_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the SMP machine hit a fatal error\n' >&2
    cat "$smp_log" >&2
    rm -f "$smp_log"
    exit 1
fi
rm -f "$smp_log"

# ── A machine too small to hold the copy: the refusal, not a crash ────
# The window needs `copy + the pool's span` inside available RAM, and a
# machine small enough has no candidate: the boot says so, stays at the link
# address and comes up anyway.  That is a branch, not a failure, and it is
# the one a small machine really takes — so it is booted rather than
# reasoned about.  The shell line is the assertion that matters: no
# relocation, no fault.
small_log="$(mktemp)"
printf '  %s\n' "timeout ${TIMEOUT_SECONDS}s $QEMU -machine q35 -smp 1 -m 128M ... -serial file: (no placement)"
set +e
timeout "${TIMEOUT_SECONDS}s" "$QEMU" \
    -machine q35 \
    -cpu max \
    -smp 1 \
    -m 128M \
    -kernel "$KERNEL_BIN" \
    -display none \
    -serial "file:$small_log" \
    -no-reboot \
    -no-shutdown \
    -netdev user,id=net0 -device virtio-net-pci,netdev=net0 >/dev/null 2>>"$small_log"
status=$?
set -e
case "$status" in
    0|124) ;;
    *)
        printf 'x86_64 KASLR check failed with exit status %s on the 128 MiB machine\n' "$status" >&2
        cat "$small_log" >&2
        rm -f "$small_log"
        exit "$status"
        ;;
esac
if ! grep -a -F "no placement in the machine's memory" "$small_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the 128 MiB machine neither relocated nor said it could not\n' >&2
    cat "$small_log" >&2
    rm -f "$small_log"
    exit 1
fi
if grep -a -F "[kaslr ] relocated" "$small_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the 128 MiB machine reports a relocation it cannot hold\n' >&2
    cat "$small_log" >&2
    rm -f "$small_log"
    exit 1
fi
if ! grep -a -F "protofire ring3 shell" "$small_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the 128 MiB machine did not reach the shell at the link address\n' >&2
    cat "$small_log" >&2
    rm -f "$small_log"
    exit 1
fi
if grep -a -F "[FATAL" "$small_log" >/dev/null 2>&1; then
    printf 'x86_64 KASLR check failed: the 128 MiB machine hit a fatal error\n' >&2
    cat "$small_log" >&2
    rm -f "$small_log"
    exit 1
fi
rm -f "$small_log"

if [ "$remove_log_on_exit" = "0" ]; then
    printf 'x86_64 KASLR log saved to %s\n' "$log_file"
fi
printf 'x86_64 KASLR check passed: table fresh, relocated boot reached a typed shell, APs online, small machine refused a placement and booted\n'
